CREATE FUNCTION dbo.LIST_SALARY22_ALL (@Forms___F_MENU_BIM___MMO INT, @Forms___Baseknow___HOLA INT, @Forms___Baseknow___HSAY INT, @Forms___Baseknow___HJAZ INT, @Forms___Baseknow___HNAH INT, @Forms___Baseknow___HCON INT, @Forms___Baseknow___HKHA INT, @HOKMDATE BIGINT, @Forms___Baseknow___SAGHFH INT, @Forms___Baseknow___HSANP INT, @Forms___Baseknow___HSHI INT, @Forms___Baseknow___YEA SMALLINT, @Forms___Baseknow___HEZA INT, @Forms___Baseknow___HBON INT, @Forms___Baseknow___HTAHOL INT) RETURNS TABLE AS RETURN ( SELECT     LIST_SALARY_END.CODE, LIST_SALARY_END.PNAME, LIST_SALARY_END.PFAMILY,                       LIST_SALARY_END.PNAME + ' ' + LIST_SALARY_END.PFAMILY AS PNPF, LIST_SALARY_END.KHNOWNUM, LIST_SALARY_END.FATHER,                       LIST_SALARY_END.BIMEH_NUM, LIST_SALARY_END.JOB, LIST_SALARY_END.SEX, LIST_SALARY_END.WSDAT, LIST_SALARY_END.WEDATE,                       LIST_SALARY_END.WDATE, LIST_SALARY_END.DAYS, LIST_SALARY_END.SALARY_DAYLY, LIST_SALARY_END.DAYS * LIST_SALARY_END.SALARY_DAYLY AS mosalary, LIST_SALARY_END.HOME * LIST_SALARY_END.DAYS AS hom,                       LIST_SALARY_END.DAYS * LIST_SALARY_END.SALARY_DAYLY + dbo.UIIF(LIST_SALARY_END.DAYS, N'=', 0, 0, LIST_SALARY_END.MAZMASH)                       AS jmazsalmash, LIST_SALARY_END.DAYS * LIST_SALARY_END.SALARY_DAYLY + dbo.UIIF(LIST_SALARY_END.DAYS, N'=', 0, 0,                       LIST_SALARY_END.MAZMASH + dbo.UIIF(@Forms___Baseknow___HOLA, N'=', - 1, LIST_SALARY_END.CHILDREN, 0)) AS jamazsalmash,                       dbo.UIIF(LIST_SALARY_END.DIHARD, N'=', 1, 0, CONVERT(INT,                       (LIST_SALARY_END.DAYS * LIST_SALARY_END.SALARY_DAYLY + dbo.UIIF(LIST_SALARY_END.DAYS, N'=', 0, 0, LIST_SALARY_END.MAZMASH))                       * 0.07)) AS bimper, LIST_SALARY_END.DAYS * LIST_SALARY_END.SALARY_DAYLY +  dbo.UIIF(LIST_SALARY_END.DAYS, N'=', 0, 0,                       LIST_SALARY_END.MAZMASH + dbo.UIIF(@Forms___Baseknow___HOLA, N'=', - 1, LIST_SALARY_END.CHILDREN, 0)) - CONVERT(INT,(LIST_SALARY_END.DAYS * LIST_SALARY_END.SALARY_DAYLY + dbo.UIIF(LIST_SALARY_END.DAYS, N'=', 0, 0, LIST_SALARY_END.MAZMASH))                       * 0.07) - dbo.PLIST_MALIAT.MALIAT AS ghabel, LIST_SALARY_END.CHILDREN AS chid, LIST_SALARY_END.CONDITIONS, LIST_SALARY_END.JAZB,                       LIST_SALARY_END.SAYER, LIST_SALARY_END.EZAFAH, LIST_SALARY_END.PADASH, LIST_SALARY_END.KASR_VAM,                       dbo.Umonth(LIST_SALARY_END.WDATE) AS MM, CONVERT(INT,                       (LIST_SALARY_END.DAYS * LIST_SALARY_END.SALARY_DAYLY + LIST_SALARY_END.HOME * LIST_SALARY_END.DAYS) * 0.07) AS bimper2,   dbo.UIIF(LIST_SALARY_END.TAB56, N'=', 0, 0,                       LIST_SALARY_END.DAYS * LIST_SALARY_END.SALARY_DAYLY + LIST_SALARY_END.HOME * LIST_SALARY_END.DAYS) AS JAMMAHS20,                       LIST_SALARY_END.DSW_IDPLC, LIST_SALARY_END.DSW_NAT, LIST_SALARY_END.DSW_BDATE, LIST_SALARY_END.MaxOfHDATE,  LIST_SALARY_END.MAZMASH,                       CAST(dbo.UIIF(LIST_SALARY_END.DAYS * LIST_SALARY_END.SALARY_DAYLY + LIST_SALARY_END.CHI + dbo.UIIF(LIST_SALARY_END.DAYS, N'=',                       0, 0, LIST_SALARY_END.MAZMASH), N'>', @Forms___Baseknow___SAGHFH,                       (LIST_SALARY_END.DAYS * LIST_SALARY_END.SALARY_DAYLY + LIST_SALARY_END.CHI + dbo.UIIF(LIST_SALARY_END.DAYS, N'=', 0, 0,                       LIST_SALARY_END.MAZMASH) - @Forms___Baseknow___SAGHFH) * 0.1, 0) AS int) AS mali, LIST_SALARY_END.TAB56,                       dbo.PLIST_MALIAT.MALIAT FROM         dbo.LIST_SALARY_END(@Forms___F_MENU_BIM___MMO, @Forms___Baseknow___HOLA, @Forms___Baseknow___HSAY,                       @Forms___Baseknow___HJAZ, @Forms___Baseknow___HNAH, @Forms___Baseknow___HCON, @Forms___Baseknow___HKHA, @HOKMDATE,                       @Forms___Baseknow___HSANP, @Forms___Baseknow___HSHI, @Forms___Baseknow___YEA, @Forms___Baseknow___HEZA,                       @Forms___Baseknow___HBON,@Forms___Baseknow___HTAHOL) LIST_SALARY_END INNER JOIN                       dbo.PLIST_MALIAT ON LIST_SALARY_END.WDATE = dbo.PLIST_MALIAT.WDATE AND LIST_SALARY_END.CODE = dbo.PLIST_MALIAT.CODE WHERE     (NOT (LIST_SALARY_END.BIMEH_NUM IS NULL)) AND (dbo.Umonth(LIST_SALARY_END.WDATE) = @Forms___F_MENU_BIM___MMO) )
